"""The starter bank: sounds generated by recipes, in tune together, with palettes, built on first use."""
from __future__ import annotations

import io
import json
import os
from contextlib import redirect_stderr, redirect_stdout
from pathlib import Path
import tempfile
import unittest

from tracker4agents import cli, mod, project, sample_intake, starter_bank
from tracker4agents.model import Module, Pattern, Sample
from tracker4agents.sample_library import SampleLibrary
from tracker4agents.usage import PERCUSSION


def run(*argv: str) -> dict:
    out, err = io.StringIO(), io.StringIO()
    with redirect_stdout(out), redirect_stderr(err):
        code = cli.main(list(argv))
    return json.loads(out.getvalue() or err.getvalue()) | {"exit": code}


class StarterBankTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.folder = Path(tempfile.mkdtemp())
        cls.result = starter_bank.build(cls.folder / "starter")
        cls.bank = SampleLibrary(cls.folder / "starter")

    def test_every_role_is_there_with_readable_names(self):
        entries = self.bank._manifest()["samples"]
        self.assertEqual(self.result["entries"], len(starter_bank.SOUNDS))
        self.assertEqual(len(entries), len(starter_bank.SOUNDS))
        roles = {entry["role"] for entry in entries}
        for role in ("kick", "snare", "hat", "cymbal", "tom", "bass", "lead", "pluck", "chord", "pad", "texture", "fx"):
            self.assertIn(role, roles)
        for entry in entries:
            self.assertEqual((entry["role_source"], entry["origin"], entry["format_origin"]),
                             ("owner", "chiploom-recipe", "mod"))
            self.assertIn("starter", entry["tags"])
            self.assertTrue(entry["compatibility"]["compatible"], entry["name"])
        self.assertEqual(self.bank.search(query="Kick Deep")["samples"][0]["role"], "kick")

    def test_every_melodic_sound_plays_c_when_c_is_written(self):
        for entry in self.bank._manifest()["samples"]:
            if entry["role"] in PERCUSSION or entry["role"] in ("texture", "fx"):
                continue
            info = sample_intake.tuning(self.bank.read_sample(entry["id"]), "mod")
            self.assertTrue(info["pitched"], entry["name"])
            self.assertEqual(info["written_c_sounds"], "C", entry["name"])
            self.assertLessEqual(abs(info["cents"]), 5, entry["name"])

    def test_palettes_insert_in_tune_and_extraction_numbers_after_them(self):
        listing = self.bank.palettes()
        self.assertEqual(listing["total"], len(starter_bank.PALETTES))
        self.assertEqual(listing["palettes"][0]["title"], "Classic 4ch")
        blank = Module("Blank", [Sample("", ())], [Pattern()], [0], metadata={"sample_source": "library"})
        module, info = self.bank.use_palette("PAL-0001", blank)
        self.assertEqual(info["inserted"], 6)
        self.assertTrue(info["tuning"]["consistent"])
        self.assertEqual([item["role"] for item in info["slot_map"]], ["kick", "snare", "hat", "bass", "chord", "lead"])
        source = self.folder / "song.mod"
        song = Module("Song", [Sample("own lead", (40,) * 16 + (-40,) * 16, 40, 0, 0, 32)], [Pattern()], [0])
        source.write_bytes(mod.encode(song))
        copy_bank = SampleLibrary(self.folder / "with-extract")
        starter_bank.build(copy_bank.path)
        copy_bank.extract(source)
        ids = [row["id"] for row in copy_bank.palettes()["palettes"]]
        self.assertEqual(ids[:5], [f"PAL-000{index}" for index in range(1, 6)])
        self.assertEqual(copy_bank.palette("PAL-0001")["title"], "Classic 4ch")

    def test_the_bank_is_deterministic(self):
        again = self.folder / "again"
        starter_bank.build(again)
        first = [entry["pcm_sha256"] for entry in self.bank._manifest()["samples"]]
        second = [entry["pcm_sha256"] for entry in SampleLibrary(again)._manifest()["samples"]]
        self.assertEqual(first, second)


class FirstUseTests(unittest.TestCase):
    def setUp(self):
        self.folder = Path(tempfile.mkdtemp())
        self.saved = {key: os.environ.get(key) for key in ("CHIPLOOM_HOME", "CHIPLOOM_BANK")}
        os.environ["CHIPLOOM_HOME"] = str(self.folder / "home")
        os.environ.pop("CHIPLOOM_BANK", None)
        self.cwd = os.getcwd()
        os.chdir(self.folder)          # no exports/sample_library here

    def tearDown(self):
        os.chdir(self.cwd)
        for key, value in self.saved.items():
            if value is None:
                os.environ.pop(key, None)
            else:
                os.environ[key] = value

    def test_without_a_bank_the_starter_bank_is_built_and_used(self):
        self.assertEqual(sample_intake.active_library(), sample_intake.starter_path())
        self.assertEqual(run("samples", "bank")["source"], "starter")
        listing = run("samples", "list", "--role", "bass", "--limit", "50")
        self.assertEqual(listing["total"], 10)
        self.assertTrue((sample_intake.starter_path() / "library.json").exists())
        built = run("samples", "bank", "--starter", str(self.folder / "elsewhere"))
        self.assertEqual(built["built"]["entries"], len(starter_bank.SOUNDS))
        self.assertEqual(Path(sample_intake.active_library()), (self.folder / "elsewhere").resolve())
        project.read_json(self.folder / "elsewhere" / "palettes.json")


if __name__ == "__main__":
    unittest.main()
